import sys, re
s=sys.stdin.read()
rows = re.findall(r'<row .*?</row>', s, re.S)
for r in rows:
    rn = re.search(r'r=\"(\d+)\"', r).group(1)
    m = re.search(r'<c r=\"A'+rn+r'\"[^>]*>.*?</c>', r, re.S)
    if m:
        cell = m.group(0)
        if 't=\"inlineStr\"' in cell:
            t = re.search(r'<t>(.*?)</t>', cell, re.S).group(1)
            print(rn, 'str', t)
        elif '<v>' in cell:
            v = re.search(r'<v>(.*?)</v>', cell, re.S).group(1)
            print(rn, 'num', v)
        else:
            print(rn, 'EMPTY-NUM')
    else:
        print(rn, 'NO-A-CELL')
